# Break My Fix finding 1, generated by Tracefix: dedupe_emails returns a wrong value.
# Property (issue): Addresses differing only in capitalisation are duplicates, so the result never contains two addresses equal ignoring case
# Quote: creates duplicates when the same email differs only in capitalisation
# Run it with pytest: it fails for as long as the code breaks this property.

from crm.contacts import dedupe_emails


def test_break_my_fix_1() -> None:
    emails = ['Bob@Example.com', 'bob@example.com']
    # The property applies to this input: all(e.isascii() and e == e.strip() for e in emails)
    result = dedupe_emails(emails=['Bob@Example.com', 'bob@example.com'])
    assert (len({r.lower() for r in result}) == len(result))
